mapper.update:
UPDATE COURSE_DATA
   SET DATA_NAME = #{dataName}
     , CONTENT   = #{content, jdbcType=CLOB}
     , MDFY_DT   = SYSDATE
 WHERE ID        = #{id}
   AND COURSE_ID = #{courseId}

mapper.delete:
UPDATE COURSE_DATA
   SET DEL_YN 	 = 'Y'
 WHERE ID        = #{id}
   AND COURSE_ID = #{courseId}

mapper.select:
SELECT COUNT(1)
  FROM COURSE C
 WHERE C.ID = #{_parameter}
